/** Orthographic frustum half-size (world units). Zoom controls magnification. */
export const _ORTHO_FRUSTUM = 10

/** Desktop auto-fit cap keeps published wide viewports from scaling models larger than the Framer canvas. */
export const _AUTO_FIT_MAX_ASPECT = 1.42

/** Minimum visible size to prevent division by zero in auto-fit calculations. */
export const _AUTO_FIT_MIN_VISIBLE = 0.0001

/** Degrees to radians conversion constant (shared across all transforms). */
export const _DEG2RAD = Math.PI / 180

/** Scroll-variant transform smoothing is always on; no user-facing panel needed. */
export const _SCROLL_SMOOTHING_SPEED = 0.08

export const easeInOutQuad = (x: number) => x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2

